    codeVi: "#include <iostream>\n#include <vector>\n\nusing namespace std;\n\n// H\u00e0m m\u1eabu ch\u1eb7t nh\u1ecb ph\u00e2n k\u1ebft qu\u1ea3 t\u1ed5ng qu\u00e1t (Monotonic Predicate: FFFFFTTTTT)\n// T\u00ecm gi\u00e1 tr\u1ecb nh\u1ecf nh\u1ea5t th\u1ecfa m\u00e3n predicate check(val) == true\ntemplate <typename F>\nlong long bs_min(long long low, long long high, F check) {\n    long long ans = high;\n    while (low <= high) {\n        long long mid = low + (high - low) / 2;\n        if (check(mid)) {\n            ans = mid;         // mid th\u1ecfa m\u00e3n, th\u1eed t\u00ecm gi\u00e1 tr\u1ecb nh\u1ecf h\u01a1n \u1edf n\u1eeda tr\u00e1i\n            high = mid - 1;\n        } else {\n            low = mid + 1;     // mid kh\u00f4ng th\u1ecfa m\u00e3n, b\u1eaft bu\u1ed9c t\u00ecm \u1edf n\u1eeda ph\u1ea3i\n        }\n    }\n    return ans;\n}\n\n// T\u00ecm gi\u00e1 tr\u1ecb l\u1edbn nh\u1ea5t th\u1ecfa m\u00e3n predicate check(val) == true (TTTTTFFFFF)\ntemplate <typename F>\nlong long bs_max(long long low, long long high, F check) {\n    long long ans = low;\n    while (low <= high) {\n        long long mid = low + (high - low) / 2;\n        if (check(mid)) {\n            ans = mid;         // mid th\u1ecfa m\u00e3n, th\u1eed t\u00ecm gi\u00e1 tr\u1ecb l\u1edbn h\u01a1n \u1edf n\u1eeda ph\u1ea3i\n            low = mid + 1;\n        } else {\n            high = mid - 1;    // mid kh\u00f4ng th\u1ecfa m\u00e3n, l\u00f9i v\u1ec1 n\u1eeda tr\u00e1i\n        }\n    }\n    return ans;\n}",
    codeEn: "#include <iostream>\n#include <vector>\n\nusing namespace std;\n\n// Generic binary search on answer (Monotonic predicate: FFFFFTTTTT)\n// Find the minimum value satisfying predicate check(val) == true\ntemplate <typename F>\nlong long bs_min(long long low, long long high, F check) {\n    long long ans = high;\n    while (low <= high) {\n        long long mid = low + (high - low) / 2;\n        if (check(mid)) {\n            ans = mid;         // mid is valid, search for a smaller valid value in the left half\n            high = mid - 1;\n        } else {\n            low = mid + 1;     // mid is invalid, must search in the right half\n        }\n    }\n    return ans;\n}\n\n// Find the maximum value satisfying predicate check(val) == true (TTTTTFFFFF)\ntemplate <typename F>\nlong long bs_max(long long low, long long high, F check) {\n    long long ans = low;\n    while (low <= high) {\n        long long mid = low + (high - low) / 2;\n        if (check(mid)) {\n            ans = mid;         // mid is valid, search for a larger valid value in the right half\n            low = mid + 1;\n        } else {\n            high = mid - 1;    // mid is invalid, search in the left half\n        }\n    }\n    return ans;\n}",
