    codeVi: "#include <iostream>\n#include <vector>\n\nusing namespace std;\n\n// S\u00e0ng SPF (Smallest Prime Factor) t\u00ednh \u01b0\u1edbc nguy\u00ean t\u1ed1 nh\u1ecf nh\u1ea5t trong O(N)\nstruct PrimeSieve {\n    int max_val;\n    vector<int> spf; // spf[x] = \u01b0\u1edbc nguy\u00ean t\u1ed1 nh\u1ecf nh\u1ea5t c\u1ee7a x\n\n    PrimeSieve(int n) : max_val(n), spf(n + 1) {\n        for (int i = 0; i <= n; ++i) spf[i] = i;\n\n        for (int i = 2; i * i <= n; ++i) {\n            if (spf[i] == i) { // i l\u00e0 s\u1ed1 nguy\u00ean t\u1ed1\n                for (int j = i * i; j <= n; j += i) {\n                    if (spf[j] == j) spf[j] = i;\n                }\n            }\n        }\n    }\n\n    // Ph\u00e2n t\u00edch th\u1eeba s\u1ed1 nguy\u00ean t\u1ed1 c\u1ee7a x trong O(log X)\n    vector<pair<int, int>> factorize(int x) const {\n        vector<pair<int, int>> factors;\n        while (x > 1) {\n            int p = spf[x];\n            int count = 0;\n            while (x % p == 0) {\n                count++;\n                x /= p;\n            }\n            factors.emplace_back(p, count);\n        }\n        return factors;\n    }\n};",
    codeEn: "#include <iostream>\n#include <vector>\n\nusing namespace std;\n\n// Linear-time Sieve with Smallest Prime Factor (SPF)\nstruct PrimeSieve {\n    int max_val;\n    vector<int> spf; // spf[x] stores the smallest prime factor of x\n\n    PrimeSieve(int n) : max_val(n), spf(n + 1) {\n        for (int i = 0; i <= n; ++i) spf[i] = i;\n\n        for (int i = 2; i * i <= n; ++i) {\n            if (spf[i] == i) { // i is prime\n                for (int j = i * i; j <= n; j += i) {\n                    if (spf[j] == j) spf[j] = i;\n                }\n            }\n        }\n    }\n\n    // Prime factorization of x in O(log x)\n    vector<pair<int, int>> factorize(int x) const {\n        vector<pair<int, int>> factors;\n        while (x > 1) {\n            int p = spf[x];\n            int count = 0;\n            while (x % p == 0) {\n                count++;\n                x /= p;\n            }\n            factors.emplace_back(p, count);\n        }\n        return factors;\n    }\n};",
