    title: "5. Greedy & Exchange Argument",
    source: "Ngu\u1ed3n tham kh\u1ea3o: USACO Guide Silver",
    codeVi: "#include <iostream>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\n// B\u00e0i to\u00e1n x\u1ebfp l\u1ecbch ho\u1ea1t \u0111\u1ed9ng (Interval Scheduling): Ch\u1ecdn nhi\u1ec1u kho\u1ea3ng kh\u00f4ng giao nhau nh\u1ea5t\nstruct Interval {\n    int start, end;\n};\n\n// H\u00e0m so s\u00e1nh s\u1eafp x\u1ebfp theo th\u1eddi gian k\u1ebft th\u00fac s\u1edbm nh\u1ea5t (kh\u00f4ng d\u00f9ng lambda)\nbool cmp(const Interval& a, const Interval& b) {\n    return a.end < b.end;\n}\n\nint schedule(vector<Interval>& a) {\n    // Ch\u1ee9ng minh Exchange Argument: Lu\u00f4n k\u1ebft th\u00fac s\u1edbm nh\u1ea5t \u0111\u1ec3 ch\u1eeba ch\u1ed7 cho c\u00e1c s\u1ef1 ki\u1ec7n sau\n    sort(a.begin(), a.end(), cmp);\n\n    int count = 0;\n    int last_end = -1e9;\n    for (const auto& cur : a) {\n        if (cur.start >= last_end) {\n            count++;\n            last_end = cur.end;\n        }\n    }\n    return count;\n}",
    codeEn: "#include <iostream>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\n// Interval Scheduling: Select maximum number of non-overlapping intervals\nstruct Interval {\n    int start, end;\n};\n\n// Standard comparator sorting by earliest finish time (no lambdas)\nbool cmp(const Interval& a, const Interval& b) {\n    return a.end < b.end;\n}\n\nint schedule(vector<Interval>& a) {\n    // Exchange argument: Earliest finish time leaves the most room for remaining events\n    sort(a.begin(), a.end(), cmp);\n\n    int count = 0;\n    int last_end = -1e9;\n    for (const auto& cur : a) {\n        if (cur.start >= last_end) {\n            count++;\n            last_end = cur.end;\n        }\n    }\n    return count;\n}",
