  6: {
    topicId: 6,
    title: "6. Graph Traversal (DFS/BFS & Grid)",
    source: "Ngu\u1ed3n tham kh\u1ea3o: CP-Algorithms",
    codeVi: "#include <iostream>\n#include <vector>\n#include <queue>\n#include <string>\n\nusing namespace std;\n\n// 1. Duy\u1ec7t theo chi\u1ec1u s\u00e2u DFS tr\u00ean danh s\u00e1ch k\u1ec1\nvoid dfs(int u, vector<bool>& vis, const vector<vector<int>>& adj) {\n    vis[u] = true;\n    for (int v : adj[u]) {\n        if (!vis[v]) {\n            dfs(v, vis, adj);\n        }\n    }\n}\n\n// 2. Duy\u1ec7t theo chi\u1ec1u r\u1ed9ng BFS tr\u00ean \u0111\u1ed3 th\u1ecb t\u1ed5ng qu\u00e1t t\u00ecm kho\u1ea3ng c\u00e1ch ng\u1eafn nh\u1ea5t\nvector<int> bfs(int src, int n, const vector<vector<int>>& adj) {\n    vector<int> dist(n, -1);\n    queue<int> q;\n\n    dist[src] = 0;\n    q.push(src);\n\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n\n        for (int v : adj[u]) {\n            if (dist[v] == -1) {\n                dist[v] = dist[u] + 1;\n                q.push(v);\n            }\n        }\n    }\n    return dist;\n}\n\n// 3. BFS tr\u00ean l\u01b0\u1edbi 2D t\u00ecm kho\u1ea3ng c\u00e1ch ng\u1eafn nh\u1ea5t (Grid BFS)\nconst int dx[4] = {-1, 1, 0, 0};\nconst int dy[4] = {0, 0, -1, 1};\n\nint bfs_grid(int start_r, int start_c, int target_r, int target_c,\n             const vector<string>& grid) {\n    int n = grid.size(), m = grid[0].size();\n    vector<vector<int>> dist(n, vector<int>(m, -1));\n    queue<pair<int, int>> q;\n\n    dist[start_r][start_c] = 0;\n    q.push({start_r, start_c});\n\n    while (!q.empty()) {\n        auto [r, c] = q.front();\n        q.pop();\n\n        if (r == target_r && c == target_c) return dist[r][c];\n\n        for (int i = 0; i < 4; ++i) {\n            int nr = r + dx[i], nc = c + dy[i];\n            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] != '#' && dist[nr][nc] == -1) {\n                dist[nr][nc] = dist[r][c] + 1;\n                q.push({nr, nc});\n            }\n        }\n    }\n    return -1; // Kh\u00f4ng \u0111\u1ebfn \u0111\u01b0\u1ee3c \u0111\u00edch\n}",
    codeEn: "#include <iostream>\n#include <vector>\n#include <queue>\n#include <string>\n\nusing namespace std;\n\n// 1. Depth-First Search (DFS) on adjacency list\nvoid dfs(int u, vector<bool>& vis, const vector<vector<int>>& adj) {\n    vis[u] = true;\n    for (int v : adj[u]) {\n        if (!vis[v]) {\n            dfs(v, vis, adj);\n        }\n    }\n}\n\n// 2. Breadth-First Search (BFS) on general graph finding shortest distance\nvector<int> bfs(int src, int n, const vector<vector<int>>& adj) {\n    vector<int> dist(n, -1);\n    queue<int> q;\n\n    dist[src] = 0;\n    q.push(src);\n\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n\n        for (int v : adj[u]) {\n            if (dist[v] == -1) {\n                dist[v] = dist[u] + 1;\n                q.push(v);\n            }\n        }\n    }\n    return dist;\n}\n\n// 3. 2D Grid BFS finding shortest path distance\nconst int dx[4] = {-1, 1, 0, 0};\nconst int dy[4] = {0, 0, -1, 1};\n\nint bfs_grid(int start_r, int start_c, int target_r, int target_c,\n             const vector<string>& grid) {\n    int n = grid.size(), m = grid[0].size();\n    vector<vector<int>> dist(n, vector<int>(m, -1));\n    queue<pair<int, int>> q;\n\n    dist[start_r][start_c] = 0;\n    q.push({start_r, start_c});\n\n    while (!q.empty()) {\n        auto [r, c] = q.front();\n        q.pop();\n\n        if (r == target_r && c == target_c) return dist[r][c];\n\n        for (int i = 0; i < 4; ++i) {\n            int nr = r + dx[i], nc = c + dy[i];\n            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] != '#' && dist[nr][nc] == -1) {\n                dist[nr][nc] = dist[r][c] + 1;\n                q.push({nr, nc});\n            }\n        }\n    }\n    return -1; // Target unreachable\n}",
  },
